import React, { useEffect, useState } from 'react';
import Swal from 'sweetalert2';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';

// --- NAVBAR ---

const Navbar = ({ cartCount, isFlying }) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();
  const isActive = (path) => location.pathname === path;

  // 1. Kan-akhdo l-email f blast l-username
  const userEmail = localStorage.getItem('email'); 

  // 2. Vérification dial l-Admin nichen
  const ADMIN_EMAIL = 'admin@fastdelice.com';
  const isAdmin = userEmail === ADMIN_EMAIL;

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  const menuLinks = [
    { name: 'Accueil', path: '/' },
    { name: 'Menu', path: '/menu' },
    { name: 'À Propos', path: '/about' },
    { name: 'Contact', path: '/contact' }
  ];

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-[1000] w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center relative">

        {/* LOGO */}
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        {/* --- DESKTOP LINKS --- */}
        <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800 items-center">
          {menuLinks.map((link) => (
            <Link 
              key={link.path} 
              to={link.path} 
              className={`relative pb-1 transition-all duration-300 hover:text-orange-600 ${isActive(link.path) ? 'text-orange-600' : ''}`}
            >
              {link.name}
              {isActive(link.path) && <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-600 rounded-full"></span>}
            </Link>
          ))}

          {/* Dashboard i-bān ghir ila kān l-email dial l-admin */}
          {isAdmin && (
            <Link to="/admin-orders" className="bg-orange-100 text-orange-600 px-3 py-1.5 rounded-lg border border-orange-200 flex items-center gap-1 hover:bg-orange-600 hover:text-white transition-all shadow-sm">
              Dashboard <span className="animate-pulse">🔔</span>
            </Link>
          )}
        </div>

        {/* --- ACTIONS --- */}
        <div className="flex items-center space-x-4">
          {/* Cart Icon */}
          <motion.div animate={isFlying ? { scale: [1, 1.3, 1] } : {}}>
            <Link to="/panier" className="relative flex items-center text-gray-800 hover:text-orange-600 pr-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center absolute -top-1 -right-1">{cartCount}</span>
            </Link>
          </motion.div>

          {/* Desktop User Info / Login */}
          <div className="hidden md:flex items-center space-x-4">
            {userEmail ? (
              <>
                {isAdmin ? (
                  <span className="bg-black text-white px-4 py-1.5 rounded-xl text-[12px] font-black uppercase italic tracking-widest border-b-4 border-orange-600 shadow-md">
                    ADMIN
                  </span>
                ) : (
                  <span className="text-sm font-black uppercase italic text-gray-700">{userEmail.split('@')[0]}</span>
                )}
                <button onClick={handleLogout} className="bg-orange-600 text-white px-5 py-2 rounded-full text-[11px] font-black uppercase hover:bg-black transition shadow-md">Quitter</button>
              </>
            ) : (
              <Link to="/login" className="bg-orange-600 text-white px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-black transition shadow-md italic">Connexion</Link>
            )}
          </div>

          {/* MOBILE TOGGLE */}
          <button className="md:hidden p-2" onClick={() => setIsOpen(!isOpen)}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} />
            </svg>
          </button>
        </div>
      </div>

      {/* --- MOBILE MENU --- */}
      <AnimatePresence>
        {isOpen && (
          <motion.div 
            initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }}
            className="absolute top-20 left-0 w-full bg-white border-b border-gray-100 flex flex-col p-6 space-y-4 md:hidden shadow-2xl z-50"
          >
            {menuLinks.map((link) => (
              <Link key={link.path} to={link.path} onClick={() => setIsOpen(false)} className={`text-lg font-black uppercase italic ${isActive(link.path) ? 'text-orange-600' : 'text-gray-800'}`}>
                {link.name}
              </Link>
            ))}
            {isAdmin && <Link to="/admin-orders" onClick={() => setIsOpen(false)} className="text-orange-600 font-black uppercase italic border-t pt-4">Panel Admin 🔒</Link>}
            <div className="border-t pt-4">
              {userEmail ? (
                <button onClick={handleLogout} className="w-full bg-black text-white p-4 rounded-2xl font-black uppercase italic">
                   Quitter {isAdmin ? '(ADMIN)' : ''}
                </button>
              ) : (
                <Link to="/login" onClick={() => setIsOpen(false)} className="block w-full bg-orange-600 text-white p-4 rounded-2xl font-black uppercase text-center italic">Connexion</Link>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};


// --- LAYOUT ---
const PageLayout = ({ children, title, isHome = false }) => (
  <div className="relative min-h-screen">
    <div className={`${isHome ? 'absolute' : 'fixed'} inset-0 z-0 h-[80vh] md:h-screen`}>
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- REGISTER ---
const Register = () => {
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });
  const [error, setError] = useState("");

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/register/', {
        username: formData.email,
        email: formData.email,
        password: formData.password,
        first_name: formData.name
      });
      localStorage.setItem('username', res.data.username || formData.name);
      localStorage.setItem('token', res.data.token);
      window.location.href = "/";
    } catch (err) {
      setError(err.response?.data?.error || "Erreur d'inscription");
    }
  };

  return (
    <PageLayout title="Inscription">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl p-12 rounded-[3.5rem] border border-white/20">
        {error && <p className="mb-4 text-red-400 text-center font-bold">{error}</p>}
        <form className="space-y-6" onSubmit={handleRegister}>
          <input type="text" placeholder="VOTRE NOM " required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, name: e.target.value})} />
          <input type="email" placeholder="VOTRE E-MAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, email: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white font-bold" 
            onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition">S'inscrire</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- LOGIN ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);
      localStorage.setItem('username', res.data.username || formData.username);
      localStorage.setItem('token', res.data.token);
      window.location.href = "/";
    } catch (err) {
      setError("❌ Identifiants incorrects.");
    }
  };

  return (
    <PageLayout title="Connexion">
      <div className="max-w-md mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem]">
        {error && <p className="mb-4 text-red-400 text-center font-bold">{error}</p>}
        <form className="space-y-6" onSubmit={handleLogin}>
          <input type="text" placeholder="Votre E-mail" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold " onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Se Connecter</button>
        </form>
      </div>
    </PageLayout>
  );
};

// --- ABOUT (Zdna fih l-ktaba) ---
const About = () => (
  <PageLayout title="Notre Passion">
    <div className="max-w-6xl mx-auto space-y-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl overflow-hidden relative">
        <div className="absolute top-0 right-0 p-10 opacity-10">
           <svg width="200" height="200" fill="white" viewBox="0 0 512 512"><path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416z"/></svg>
        </div>

        <h3 className="text-4xl font-black text-orange-600 italic mb-8 uppercase tracking-tighter text-center">Plus Qu'un Simple Restaurant</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-center">
          <div className="space-y-6 text-white text-lg leading-relaxed font-medium italic opacity-95">
            <p>
              Depuis notre ouverture en **2026**, FastDélice s'est imposé comme une référence incontournable de la gastronomie rapide au Maroc. Notre concept est né d'une idée simple : allier la rapidité du service à l'exigence de la haute cuisine.
            </p>
            <p>
              Chaque ingrédient est sélectionné avec le plus grand soin auprès de nos producteurs locaux. Nos légumes sont cueillis le matin même et nos viandes sont garanties 100% fraîches.
            </p>
            <p className="border-l-4 border-orange-600 pl-6 py-2 bg-orange-600/10 rounded-r-xl">
              "La qualité n'est pas un luxe, c'est notre engagement quotidien envers chaque client qui franchit notre porte."
            </p>
          </div>

          <div className="space-y-6 text-white text-lg leading-relaxed font-medium italic opacity-95">
            <p>
              Notre secret réside dans notre pâte à pizza artisanale, pétrie à la main et reposée durant 48 heures pour garantir une légèreté et un croustillant incomparables.
            </p>
            <p>
              L'équipe FastDélice, c'est avant tout une famille de passionnés, des chefs aux livreurs, tous unis pour vous offrir une expérience mémorable, que ce soit sur place dans notre ambiance feutrée ou chez vous.
            </p>
            <div className="pt-6 flex gap-10">
               <div><p className="text-4xl font-black text-orange-600">15+</p><p className="text-xs uppercase font-bold tracking-widest">Spécialités</p></div>
               <div><p className="text-4xl font-black text-orange-600">10k</p><p className="text-xs uppercase font-bold tracking-widest">Clients Heureux</p></div>
               <div><p className="text-4xl font-black text-orange-600">30min</p><p className="text-xs uppercase font-bold tracking-widest">Livraison Max</p></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </PageLayout>
);

// --- CONTACT ---
const Contact = () => (
  <PageLayout title="Contactez-Nous">
    <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-10">
      <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-10 rounded-[3rem] shadow-2xl">
        <h3 className="text-2xl font-black text-orange-600 italic mb-6 uppercase">Coordonnées</h3>
        <div className="space-y-6 text-white font-medium italic">
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Adresse</p><p>123 Boulevard Gourmand, Casablanca</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Téléphone</p><p>+212 522 12 34 56</p></div>
          <div><p className="text-orange-500 font-black text-[10px] uppercase mb-1 tracking-widest">Email</p><p>contact@fastdelice.ma</p></div>
        </div>
      </div>
      <form className="bg-black/40 backdrop-blur-xl border border-white/10 p-10 rounded-[3rem] space-y-4">
        <input type="text" placeholder="NOM" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-xs font-bold uppercase outline-none focus:border-orange-600 transition" />
        <textarea placeholder="MESSAGE" rows="4" className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white text-xs font-bold uppercase outline-none focus:border-orange-600 transition"></textarea>
        <button className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Envoyer</button>
      </form>
    </div>
  </PageLayout>
);

// --- HOME ---
const Home = () => {
  const testimonials = [
    { n: "SARAH B.", t: "La meilleure pizza que j'ai mangée à Fès!", s: "★★★★★" },
    { n: "AHMED L.", t: "Livraison rapide et plats chauds. Top!", s: "★★★★★" },
    { n: "YOUSSEF M.", t: "Qualité exceptionnelle pour le prix.", s: "★★★★" }
  ];
  return (
    <div className="flex flex-col min-h-screen bg-white">
      <div className="relative h-[90vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="Hero" />
          <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px]"></div>
        </div>
        <div className="relative z-10 text-center px-6">
          <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic">Fast<span className="text-orange-600">Délice</span></h1>
          <p className="text-xl text-white mb-12 font-black italic opacity-90">"La passion du goût, l'élégance du service."</p>
          <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
        </div>
      </div>
      <div className="bg-white py-24 px-6">
        <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-8">
          {testimonials.map((v, i) => (
            <div key={i} className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 text-center">
              <div className="text-orange-500 mb-6 text-sm">{v.s}</div>
              <p className="text-gray-700 italic font-bold mb-8 text-lg leading-relaxed">"{v.t}"</p>
              <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest">— {v.n}</span>
            </div>
          ))}
        </div>
      </div>
      <footer className="bg-gray-50 py-8 border-t border-gray-100 text-center">
        <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">© 2026 FAST DÉLICE. TOUS DROITS RÉSERVÉS.</p>
      </footer>
    </div>
  );
};

// --- MENU ---
const Menu = ({ categories, addToCart, isFlying }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeCategory, setActiveCategory] = useState("Tout");

  const allDishes = categories.flatMap(c => (c.dishes || []).map(dish => ({ ...dish, categoryName: c.name })));

  const filteredDishes = allDishes.filter(item => 
    (activeCategory === "Tout" || item.categoryName === activeCategory) && 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <PageLayout title="Menu">
      {/* 🔍 RECHERCHE - Responsive width */}
      <div className="max-w-md mx-auto mb-8 px-4">
        <input 
          type="text" 
          placeholder="RECHERCHER UN PLAT..." 
