// --- ADMIN ORDERS DASHBOARD ---
const AdminOrders = () => {
  const [orders, setOrders] = useState([]);
  const [lastCount, setLastCount] = useState(0);
  const [categories, setCategories] = useState([]);
  const [allDishes, setAllDishes] = useState([]);
  const [newCategoryName, setNewCategoryName] = useState("");

  const [newDish, setNewDish] = useState({
    name: '',
    price: '',
    description: '',
    category: '', 
    image: null
  });

  const fetchData = async () => {
    try {
      const [ordRes, catRes, dishRes] = await Promise.all([
        axios.get('http://127.0.0.1:8000/api/orders/'),
        axios.get('http://127.0.0.1:8000/api/categories/'),
        axios.get('http://127.0.0.1:8000/api/dishes/')
      ]);
      setOrders(ordRes.data);
      setCategories(catRes.data);
      setAllDishes(dishRes.data);

      if (ordRes.data.length > lastCount && lastCount !== 0) {
        new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3').play();
      }
      setLastCount(ordRes.data.length);
    } catch (e) { console.log("Erreur:", e); }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => clearInterval(interval);
  }, [lastCount]);

  const handleAddCategory = async () => {
    if (!newCategoryName) return Swal.fire('Attention', 'Veuillez saisir le nom de la catégorie.', 'warning');
    try {
      const res = await axios.post('http://127.0.0.1:8000/api/categories/', { name: newCategoryName });
      setCategories([...categories, res.data]); 
      setNewCategoryName(""); 
      Swal.fire('Succès !', 'Catégorie ajoutée.', 'success');
    } catch (e) { Swal.fire('Erreur', "Impossible d'ajouter la catégorie.", 'error'); }
  };

  const handleAddDish = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    Object.keys(newDish).forEach(key => formData.append(key, newDish[key]));
    try {
      await axios.post('http://127.0.0.1:8000/api/dishes/', formData);
      Swal.fire('Succès !', 'Plat ajouté au menu.', 'success');
      setNewDish({ name: '', price: '', description: '', category: '', image: null });
      fetchData(); 
    } catch (error) { Swal.fire('Erreur', 'Vérifiez les informations.', 'error'); }
  };

  const handleDeleteDish = async (id) => {
    const result = await Swal.fire({
      title: 'Supprimer ce plat ?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#000000',
      cancelButtonColor: '#EA580C',
      confirmButtonText: 'Oui, supprimer',
      cancelButtonText: 'Annuler'
    });

    if (result.isConfirmed) {
      try {
        await axios.delete(`http://127.0.0.1:8000/api/dishes/${id}/`);
        setAllDishes(allDishes.filter(d => d.id !== id));
        Swal.fire('Supprimé !', 'Le plat a été retiré.', 'success');
      } catch (e) { Swal.fire('Erreur', 'Action impossible.', 'error'); }
    }
  };

  const handleDone = async (orderId) => {
    try {
      await axios.delete(`http://127.0.0.1:8000/api/orders/${orderId}/`);
      setOrders(orders.filter(order => order.id !== orderId));
      Swal.fire({ title: 'Prêt !', icon: 'success', timer: 1000, showConfirmButton: false });
    } catch (e) { console.error(e); }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6 md:p-10 text-gray-900 font-sans">
      <div className="max-w-5xl mx-auto">

        {/* --- SECTION: GÉRER LES CATÉGORIES (Couleur Orange/Noir) --- */}
        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm mb-6 border border-orange-100">
          <h2 className="text-xl font-black uppercase italic mb-4 text-orange-600">
              📁 Gestion des Catégories
          </h2>
          <div className="flex gap-4">
            <input 
              type="text" 
              placeholder="Ex : Tacos, Burgers..." 
              className="flex-1 border-2 border-gray-100 p-3 rounded-xl focus:border-orange-500 outline-none transition"
              value={newCategoryName}
              onChange={(e) => setNewCategoryName(e.target.value)}
            />
            <button 
              onClick={handleAddCategory}
             className="w-full md:w-auto bg-orange-600 text-white px-10 py-3 rounded-xl font-black uppercase text-xs hover:bg-black transition-all shadow-md hover:shadow-orange-200 active:scale-95"
            >
             Ajouter +
            </button>
          </div>
        </div>

        {/* SECTION 1: AJOUTER PLAT */}
        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm mb-12 border border-orange-100">
          <h2 className="text-2xl font-black uppercase italic mb-6">➕ Nouveau Plat</h2>
          <form onSubmit={handleAddDish} className="grid grid-cols-2 gap-4">
            <input type="text" placeholder="Nom" className="border-2 p-3 rounded-xl focus:border-orange-500 outline-none" onChange={(e) => setNewDish({...newDish, name: e.target.value})} required value={newDish.name}/>
            <input type="number" placeholder="Prix" className="border-2 p-3 rounded-xl focus:border-orange-500 outline-none" onChange={(e) => setNewDish({...newDish, price: e.target.value})} required value={newDish.price}/>
            <select className="border-2 p-3 rounded-xl focus:border-orange-500 outline-none" onChange={(e) => setNewDish({...newDish, category: e.target.value})} required value={newDish.category}>
              <option value="">Catégorie</option>
              {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
            </select>
            <input type="file" className="p-2 text-xs border-2 border-dashed border-gray-100 rounded-xl" onChange={(e) => setNewDish({...newDish, image: e.target.files[0]})} />
            <textarea placeholder="Description..." className="col-span-2 border-2 p-3 rounded-xl focus:border-orange-500 outline-none" onChange={(e) => setNewDish({...newDish, description: e.target.value})} value={newDish.description}></textarea>
            <button type="submit" className="col-span-2 bg-orange-600 text-white font-black p-4 rounded-2xl hover:bg-black transition shadow-lg uppercase italic">Ajouter au Menu</button>
          </form>
        </div>

        {/* SECTION 2: GÉRER LE MENU (Liste avec icône Poubelle) */}
        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm mb-12 border border-gray-100">
          <h2 className="text-2xl font-black uppercase italic mb-6">🗑️ Menu Actuel</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {allDishes.map(dish => (
              <div key={dish.id} className="flex justify-between items-center p-4 border border-gray-50 rounded-2xl bg-gray-50/50 hover:bg-white transition group">
                <span className="font-bold text-gray-700 uppercase italic text-sm">{dish.name} — {dish.price} DH</span>
                <button 
                  onClick={() => handleDeleteDish(dish.id)} 
                  className="bg-gray-100 text-gray-400 p-2 rounded-lg hover:bg-red-50 hover:text-red-600 transition"
                  title="Supprimer"
                >
                  <span role="img" aria-label="delete">🗑️</span>
                </button>
              </div>
            ))}
          </div>
        </div>

        {/* SECTION 3: COMMANDES */}
        <h1 className="text-4xl font-black uppercase italic mb-10 border-l-8 border-orange-600 pl-4">Commandes 🔔</h1>
        <div className="grid gap-6">
          {orders.map(order => (
            <div key={order.id} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 flex justify-between items-center">
              <div>
                <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest">#{order.id} • {order.order_type}</span>
                <h3 className="text-2xl font-black text-black uppercase italic">{order.full_name}</h3>
                <p className="text-gray-500 font-bold italic mt-2">{order.items}</p>
              </div>
              <div className="text-right">
                <p className="text-3xl font-black text-black">{order.total_price} DH</p>
                <button onClick={() => handleDone(order.id)} className="mt-4 bg-black text-white px-8 py-3 rounded-2xl text-[11px] font-black uppercase hover:bg-orange-600 transition shadow-lg">Marquer comme prêt ✅</button>
              </div>
            </div>
          ))}
        </div>

      </div>
    </div>
  );
};

// --- MAIN APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);
  const [orderType, setOrderType] = useState(""); 
  const [isFlying, setIsFlying] = useState(false);

  const triggerFly = () => {
    setIsFlying(true);
    // Zdna lwaqt l 1000ms bach t-ban l-vibration mzyan f l-navbar
    setTimeout(() => setIsFlying(false), 1000); 
  };

  const addToCart = (dish) => {
    triggerFly();
    setOrderType(dish.type);
    setCart((prev) => {
      const existing = prev.find(item => item.id === dish.id);
      if (existing) {
        return prev.map(item => item.id === dish.id ? { ...item, quantity: (item.quantity || 1) + 1 } : item);
      }
      return [...prev, { ...dish, quantity: 1, type: dish.type }];
    });
  };

  const validateOrder = async () => {
    const user = localStorage.getItem('username'); // Smyt l-user li m-connecté

    if (!user) {
      Swal.fire({
        title: "Connexion Requise",
        text: "Veuillez vous connecter pour passer commande.",
        icon: "warning",
        confirmButtonColor: "#ea580c"
      });
      return;
    }

    if (cart.length === 0) return;

    // 1. N-7sbo l-total
    const total = cart.reduce((acc, item) => acc + (parseFloat(item.price) * (item.quantity || 1)), 0);

    // 2. N-jm3o l-items f text wa7ed (ex: Pizza x2, Coca x1)
    const itemsSummary = cart.map(i => `${i.name} (x${i.quantity || 1})`).join(', ');

    // 3. L-data li ghadi t-ssift l Django
    const orderData = {
      full_name: user,
      items: itemsSummary,
      total_price: total,
      order_type: orderType || "Sur place", 
      status: "En attente"
    };

    try {
      // --- HNA L-KHIDMA L-JDIDA (CONNECT M3A DJANGO) ---
      await axios.post('http://127.0.0.1:8000/api/orders/', orderData);

      Swal.fire({
        title: 'C’est noté ! 🍕',
        text: 'Votre commande est en cuisine. Préparez-vous à vous régaler !',
        icon: 'success',
        confirmButtonColor: '#ff5722', // L-orange dialek
        confirmButtonText: 'Parfait !'
      }).then(() => {
        setCart([]);
        window.location.href = "/";
      });
    } catch (error) {
      console.error("Erreur API:", error);
      Swal.fire({
        title: 'Erreur',
        text: "Impossible d'envoyer la commande. Vérifie que Django est allumé.",
        icon: 'error'
      });
    }
  };

  const updateQuantity = (id, amount) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(1, (item.quantity || 1) + amount) } : item));
  };

  const removeFromCart = (id) => setCart(prev => prev.filter(item => item.id !== id));

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} isFlying={isFlying} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/admin-orders" element={<AdminOrders />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} isFlying={isFlying} />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/panier" element={<Panier cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart} validateOrder={validateOrder} orderType={orderType} />} />
        </Routes>
      </div>
    </Router>
  );
}
